class GlyphEngine final : public QIconEngine {
public:
    explicit GlyphEngine(const QString& glyph) : m_glyph(glyph) {}
    QIconEngine* clone() const override { return new GlyphEngine(m_glyph); }
    QPixmap pixmap(const QSize& size, QIcon::Mode mode, QIcon::State) override {
        QPixmap pm(size);
        pm.fill(Qt::transparent);
        fluent::FontIcon renderer(m_glyph);
        renderer.setIconSize(qMin(size.width(), size.height()));
        renderer.setEnabled(mode != QIcon::Disabled);
        renderer.resize(size);
        QPainter painter(&pm);
        renderer.render(&painter, QPoint(), QRegion(), QWidget::DrawChildren);
        return pm;
    }
    void paint(QPainter* painter, const QRect& rect, QIcon::Mode mode, QIcon::State state) override {
        const int dpr = painter->device() ? qMax(1, qRound(painter->device()->devicePixelRatioF())) : 1;
        painter->drawPixmap(rect, pixmap(rect.size() * dpr, mode, state));
    }
private:
    QString m_glyph;
};
auto* control = new fluent::menus_toolbars::FluentMenu(QStringLiteral("File"), %PARENT%);
auto addCommand = [&](const QString& text, const QString& glyph, QKeySequence::StandardKey shortcut) {
    auto* action = new QAction(text, control);
    action->setIcon(QIcon(new GlyphEngine(glyph)));
    if (shortcut != QKeySequence::UnknownKey)
        action->setShortcut(shortcut);
    control->addAction(action);
    return action;
};
addCommand(QStringLiteral("New"), Typography::Icons::Add, QKeySequence::New);
addCommand(QStringLiteral("Open..."), Typography::Icons::Folder, QKeySequence::Open);
addCommand(QStringLiteral("Save"), Typography::Icons::Save, QKeySequence::Save);
control->addSeparator();
auto* wrap = control->addAction(QStringLiteral("Word wrap"));
wrap->setCheckable(true);
